3. use std::{iter, ops::Neg, ptr};
4. 
5. use ark_bls12_381::{Bls12_381, Fq12, Fr as BlsFr, G1Affine, G2Affine};
6. use ark_groth16::{Proof, VerifyingKey};
7. use ark_relations::r1cs::SynthesisError;
8. 
9. use ark_serialize::{CanonicalDeserialize, CanonicalSerialize};
10. use blst::{
11.     blst_final_exp, blst_fp, blst_fp12, blst_fr, blst_miller_loop, blst_p1, blst_p1_add_or_double,
12.     blst_p1_affine, blst_p1_from_affine, blst_p1_mult, blst_p1_to_affine, blst_p1s_mult_pippenger,
13.     blst_p1s_mult_pippenger_scratch_sizeof, blst_scalar, blst_scalar_from_fr, limb_t, Pairing,
14. };
15. use fastcrypto::error::FastCryptoError;
16. 
17. use crate::conversions::{
18.     bls_fq12_to_blst_fp12, bls_fr_to_blst_fr, bls_g1_affine_to_blst_g1_affine,
19.     bls_g2_affine_to_blst_g2_affine, blst_fp12_to_bls_fq12, G1_COMPRESSED_SIZE,
20. };
21. 
22. #[cfg(test)]
23. #[path = "unit_tests/verifier_tests.rs"]
24. mod verifier_tests;
25. 
26. /// This is a helper function to store a pre-processed version of the verifying key.
27. /// This is roughly homologous to [`ark_groth16::PreparedVerifyingKey`].
28. /// Note that contrary to Arkworks, we don't store a "prepared" version of the gamma_g2_neg_pc,
29. /// delta_g2_neg_pc fields, because we can't use them with blst's pairing engine.
30. #[derive(Clone, Debug, PartialEq, Eq)]
31. pub struct PreparedVerifyingKey {
32.     /// The element vk.gamma_abc_g1,
33.     /// aka the `[gamma^{-1} * (beta * a_i + alpha * b_i + c_i) * G]`, where i spans the public inputs
34.     pub vk_gamma_abc_g1: Vec<G1Affine>,
35.     /// The element `e(alpha * G, beta * H)` in `E::GT`.
36.     pub alpha_g1_beta_g2: blst_fp12,
37.     /// The element `- gamma * H` in `E::G2`, for use in pairings.
38.     pub gamma_g2_neg_pc: G2Affine,
39.     /// The element `- delta * H` in `E::G2`, for use in pairings.
40.     pub delta_g2_neg_pc: G2Affine,
