26. #[inline]
27. fn u64s_from_bytes(bytes: &[u8; 32]) -> [u64; 4] {
28.     [
29.         u64::from_le_bytes(bytes[0..8].try_into().unwrap()),
30.         u64::from_le_bytes(bytes[8..16].try_into().unwrap()),
31.         u64::from_le_bytes(bytes[16..24].try_into().unwrap()),
32.         u64::from_le_bytes(bytes[24..32].try_into().unwrap()),
33.     ]
34. }
