115. // Target Field conversions
116. 
117. /// Convert an Arkworks BLS12-381 degree-6 extension field element to a blst degree-6 extension
118. /// field element.
119. pub fn bls_fq6_to_blst_fp6(f: &Fq6) -> blst_fp6 {
120.     let c0 = bls_fq2_to_blst_fp2(&f.c0);
121.     let c1 = bls_fq2_to_blst_fp2(&f.c1);
122.     let c2 = bls_fq2_to_blst_fp2(&f.c2);
123.     blst_fp6 { fp2: [c0, c1, c2] }
124. }
125. 
126. /// Convert a blst degree-6 extension field element to an Arkworks BLS12-381 degree-6 extension
127. /// field element.
128. pub fn blst_fp6_to_bls_fq6(f: &blst_fp6) -> Fq6 {
129.     let c0 = blst_fp2_to_bls_fq2(&f.fp2[0]);
130.     let c1 = blst_fp2_to_bls_fq2(&f.fp2[1]);
131.     let c2 = blst_fp2_to_bls_fq2(&f.fp2[2]);
132.     Fq6::new(c0, c1, c2)
133. }
