135. /// Convert an Arkworks BLS12-381 target field element to a blst target field element.
136. pub fn bls_fq12_to_blst_fp12(f: &Fq12) -> blst_fp12 {
137.     let c0 = bls_fq6_to_blst_fp6(&f.c0);
138.     let c1 = bls_fq6_to_blst_fp6(&f.c1);
139.     blst_fp12 { fp6: [c0, c1] }
140. }
