60.     fn fmt(&self, f: &mut Formatter<'_>) -> FmtResult {
61.         match self.infinity {
62.             true => write!(f, "infinity"),
63.             false => write!(f, "({}, {})", self.x, self.y),
64.         }
65.     }
66. }
67. 
68. impl<P: SWCurveConfig> Affine<P> {
69.     /// Constructs a group element from x and y coordinates.
70.     /// Performs checks to ensure that the point is on the curve and is in the right subgroup.
71.     pub fn new(x: P::BaseField, y: P::BaseField) -> Self {
72.         let point = Self {
73.             x,
74.             y,
75.             infinity: false,
76.         };
77.         assert!(point.is_on_curve());
78.         assert!(point.is_in_correct_subgroup_assuming_on_curve());
79.         point
80.     }
81. 
82.     /// Constructs a group element from x and y coordinates.
83.     ///
84.     /// # Warning
85.     ///
86.     /// Does *not* perform any checks to ensure the point is in the curve or
87.     /// is in the right subgroup.
88.     pub const fn new_unchecked(x: P::BaseField, y: P::BaseField) -> Self {
89.         Self {
90.             x,
91.             y,
92.             infinity: false,
93.         }
94.     }
95. 
96.     pub const fn identity() -> Self {
97.         Self {
98.             x: P::BaseField::ZERO,
99.             y: P::BaseField::ZERO,
100.             infinity: true,
101.         }
102.     }
103. 
104.     /// Attempts to construct an affine point given an x-coordinate. The
105.     /// point is not guaranteed to be in the prime order subgroup.
106.     ///
107.     /// If and only if `greatest` is set will the lexicographically
108.     /// largest y-coordinate be selected.
109.     #[allow(dead_code)]
110.     pub fn get_point_from_x_unchecked(x: P::BaseField, greatest: bool) -> Option<Self> {
111.         Self::get_ys_from_x_unchecked(x).map(|(smaller, larger)| {
112.             if greatest {
113.                 Self::new_unchecked(x, larger)
114.             } else {
115.                 Self::new_unchecked(x, smaller)
116.             }
117.         })
118.     }
119. 
120.     /// Returns the two possible y-coordinates corresponding to the given x-coordinate.
121.     /// The corresponding points are not guaranteed to be in the prime-order subgroup,
122.     /// but are guaranteed to be on the curve. That is, this method returns `None`
123.     /// if the x-coordinate corresponds to a non-curve point.
