138.     let c1 = bls_fq6_to_blst_fp6(&f.c1);
139.     blst_fp12 { fp6: [c0, c1] }
140. }
141. 
142. /// Convert a blst target field element to an Arkworks BLS12-381 target field element.
143. pub fn blst_fp12_to_bls_fq12(f: &blst_fp12) -> Fq12 {
144.     let c0 = blst_fp6_to_bls_fq6(&f.fp6[0]);
145.     let c1 = blst_fp6_to_bls_fq6(&f.fp6[1]);
146.     Fq12::new(c0, c1)
147. }
