40. // This emulates the process_vk function of the arkworks verifier, but using blst to compute the term
41. // alpha_g1_beta_g2. See [`test_prepare_vk`].
42. fn ark_process_vk(vk: &VerifyingKey<Bls12_381>) -> PreparedVerifyingKey<Bls12_381> {
43.     let g1_alpha = bls_g1_affine_to_blst_g1_affine(&vk.alpha_g1);
44.     let g2_beta = bls_g2_affine_to_blst_g2_affine(&vk.beta_g2);
45.     let blst_alpha_g1_beta_g2 = {
46.         let mut tmp = blst_fp12::default();
47.         unsafe { blst_miller_loop(&mut tmp, &g2_beta, &g1_alpha) };
48. 
49.         let mut out = blst_fp12::default();
50.         unsafe { blst_final_exp(&mut out, &tmp) };
51.         out
52.     };
53.     let alpha_g1_beta_g2 = blst_fp12_to_bls_fq12(&blst_alpha_g1_beta_g2);
54.     PreparedVerifyingKey {
55.         vk: vk.clone(),
56.         alpha_g1_beta_g2,
57.         gamma_g2_neg_pc: vk.gamma_g2.neg().into(),
58.         delta_g2_neg_pc: vk.delta_g2.neg().into(),
59.     }
60. }
