62. // This computes the result of the multi-pairing involved in the Groth16 verification, using arkworks.
63. // See [`test_multipairing_with_processed_vk`]
64. fn ark_multipairing_with_prepared_vk(
65.     pvk: &PreparedVerifyingKey<Bls12_381>,
66.     proof: &Proof<Bls12_381>,
67.     public_inputs: &[Fr],
68. ) -> Fq12 {
69.     let mut g_ic = pvk.vk.gamma_abc_g1[0].into_projective();
70.     for (i, b) in public_inputs.iter().zip(pvk.vk.gamma_abc_g1.iter().skip(1)) {
71.         g_ic.add_assign(&b.mul(i.into_repr()));
72.     }
73. 
74.     let qap = Bls12_381::miller_loop(
75.         [
76.             (proof.a.into(), proof.b.into()),
77.             (g_ic.into_affine().into(), pvk.gamma_g2_neg_pc.clone()),
78.             (proof.c.into(), pvk.delta_g2_neg_pc.clone()),
79.         ]
80.         .iter(),
81.     );
82. 
83.     Bls12_381::final_exponentiation(&qap).unwrap()
84. }
