88. proptest! {
89.     // This technical test is necessary because blst does not expose a generic multi-miller
90.     // loop  operation, and forces us to abuse the signature-oriented pairing engine
91.     // that it does expose. Here we show the use of the pairing engine is equivalent to iterated
92.     // use of one-off pairings.
93.     // see https://github.com/supranational/blst/issues/136
94.     #[test]
95.     fn test_blst_miller_loops(
96.         a_s in collection::vec(arb_blst_g1_affine().prop_filter("values must be non-infinity", |v| unsafe{!blst_p1_affine_is_inf(v)}), LEN..=LEN),
97.         b_s in collection::vec(arb_blst_g2_affine().prop_filter("values must be non-infinity", |v| unsafe{!blst_p2_affine_is_inf(v)}), LEN..=LEN)
98.     ) {
99.         let pairing_engine_result = {
100.             let dst = [0u8; 3];
101.             let mut pairing_blst = Pairing::new(false, &dst);
102.             for (b, a) in b_s.iter().zip(a_s.iter()) {
103.                 pairing_blst.raw_aggregate(b, a);
104.             }
105.             pairing_blst.as_fp12() // this implies pairing_blst.commit()
106.         };
107. 
108.         let mut res = blst_fp12::default();
109.         let mut loop0 = blst_fp12::default();
110. 
111.         for i in 0..LEN {
112.             unsafe {
113.                 blst_miller_loop(&mut loop0, b_s[i..].as_ptr(), a_s[i..].as_ptr());
114.                 blst_fp12_mul(&mut res, &res, &loop0);
115.                 loop0 = blst_fp12::default();
116.             }
117.         }
118. 
119.         prop_assert_eq!(res, pairing_engine_result);
120.     }
121. 
122. }
