     let (pk, vk) = Groth16::<Bls12_381>::circuit_specific_setup(c, rng).unwrap();
     let proof = Groth16::<Bls12_381>::prove(&pk, c, rng).unwrap();
     let v = c.a.unwrap().mul(c.b.unwrap());

     let ark_pvk = Groth16::<Bls12_381>::process_vk(&vk).unwrap();
